    @SuppressWarnings("unchecked") @Test public void scannedAppendPreservesPasswordAndBatchImportChoices()throws Exception{
        File source=locked("qa-scan-append");Bitmap image=Bitmap.createBitmap(400,600,Bitmap.Config.ARGB_8888);image.eraseColor(Color.WHITE);File photo=new File(f.dir,"qa-import.png");try(OutputStream out=new FileOutputStream(photo)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();String uri=Uri.fromFile(photo).toString();Activity editor=launch(ScanEditorActivity.class,new Intent().putStringArrayListExtra("pages",new ArrayList<>(Arrays.asList(uri,uri))).putExtra("capture_mode","Batch").putExtra("start_crop",true).putExtra("initial_filter",0).putExtra("auto_detect",false).putExtra("append_path",source.getPath()).putExtra("append_password","secret123"));await(()->!(Boolean)f.field(editor,"loadingPage"));assertEquals(Arrays.asList(0,0),f.field(editor,"filters"));assertTrue(((Set<String>)f.field(editor,"detectedPages")).contains(uri+"#0"));Instrumentation.ActivityMonitor monitor=inst.addMonitor(PdfViewerActivity.class.getName(),null,false);call(editor,"save",new Class<?>[0]);Activity viewer=inst.waitForMonitorWithTimeout(monitor,30000);inst.removeMonitor(monitor);assertNotNull(viewer);activities.add(viewer);File result=new File(viewer.getIntent().getStringExtra("path"));outputs.add(result);protectedCopy(result,4);
    }
    @Test public void keywordReviewMarksAllMatchesAndInlineSelectionCopiesText()throws Exception{
        File source=f.nativePdf("qa-keyword-ui.pdf",2);Activity editor=launch(PdfEditActivity.class,new Intent().putExtra("path",source.getPath()));await(()->!(Boolean)f.field(editor,"busy"));call(editor,"findRedactions",new Class<?>[]{String.class,boolean.class},"Invoice",true);await(()->!(Boolean)f.field(editor,"busy"));inst.waitForIdleSync();inst.runOnMainSync(()->{boolean clicked=false;for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){android.widget.Button button=root.findViewById(android.R.id.button1);if(button!=null&&"Mark selected".contentEquals(button.getText())){android.widget.ListView list=findList(root);assertNotNull("Match list must be visible",list);assertEquals(2,list.getCount());assertTrue(list.isShown());button.performClick();clicked=true;break;}}assertTrue(clicked);});inst.waitForIdleSync();await(()->((ArrayList<?>)f.field(editor,"marks")).size()==2);assertEquals(2,((ArrayList<?>)f.field(editor,"marks")).size());
        PdfEditActivity.Mark first=(PdfEditActivity.Mark)((ArrayList<?>)f.field(editor,"marks")).get(0);RectF marked=new RectF(first.bounds);Instrumentation.ActivityMonitor redactedMonitor=inst.addMonitor(PdfViewerActivity.class.getName(),null,false);call(editor,"write",new Class<?>[]{boolean.class},true);Activity redacted=inst.waitForMonitorWithTimeout(redactedMonitor,30000);inst.removeMonitor(redactedMonitor);assertNotNull(redacted);activities.add(redacted);File redactedFile=new File(redacted.getIntent().getStringExtra("path"));outputs.add(redactedFile);try(PDDocument doc=PDDocument.load(redactedFile)){assertEquals(2,doc.getNumberOfPages());assertTrue(new PDFTextStripper().getText(doc).trim().isEmpty());Bitmap rendered=PdfLayout.render(doc,0,600,800);assertEquals(Color.BLACK,rendered.getPixel((int)(marked.centerX()*rendered.getWidth()),(int)(marked.centerY()*rendered.getHeight())));rendered.recycle();}

        Activity viewer=launch(PdfViewerActivity.class,new Intent().putExtra("path",source.getPath()));await(()->!((ArrayList<?>)f.field(viewer,"slots")).isEmpty());call(viewer,"selectOnPage",new Class<?>[]{int.class,String.class},0,null);await(()->f.field(viewer,"selection")!=null);Object selection=f.field(viewer,"selection");ArrayList<?> glyphs=(ArrayList<?>)f.field(selection,"glyphs");f.set(selection,"start",0);f.set(selection,"end",glyphs.size()-1);String text=(String)f.invoke(selection,"selectedText",new Class<?>[0]);assertTrue(text,text.contains("Invoice"));
    }
    @Test public void launcherCameraPreferenceAndSingleBookHint()throws Exception{
        SharedPreferences prefs=c.getSharedPreferences("scan_defaults",0);boolean previous=prefs.getBoolean("launch_camera",false);prefs.edit().putBoolean("launch_camera",true).commit();Instrumentation.ActivityMonitor monitor=inst.addMonitor(CameraCaptureActivity.class.getName(),null,false);Instrumentation.ActivityMonitor mainMonitor=inst.addMonitor(MainActivity.class.getName(),null,false);
        try{inst.runOnMainSync(()->c.startActivity(new Intent(c,MainActivity.class).setAction(Intent.ACTION_MAIN).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK)));Activity camera=inst.waitForMonitorWithTimeout(monitor,15000);assertNotNull(camera);activities.add(camera);Activity main=inst.waitForMonitorWithTimeout(mainMonitor,1000);if(main!=null)activities.add(main);CameraCaptureSession session=(CameraCaptureSession)f.field(camera,"session");session.mode="Book";session.bookDoublePage=false;assertTrue(((String)f.invoke(camera,"guideText",new Class<?>[0])).contains("one page"));session.bookDoublePage=true;assertTrue(((String)f.invoke(camera,"guideText",new Class<?>[0])).contains("two pages"));}
        finally{prefs.edit().putBoolean("launch_camera",previous).commit();inst.removeMonitor(monitor);inst.removeMonitor(mainMonitor);}
    }
    @Test public void generalImportRoutesOfficeFileIntoLocalConversion()throws Exception{
        File document=new File(c.getFilesDir(),"documents/qa-office-"+System.nanoTime()+".docx");outputs.add(document);try(InputStream in=inst.getContext().getAssets().open("office-fixtures/external.docx");OutputStream out=new FileOutputStream(document)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,document.getName());values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"application/vnd.openxmlformats-officedocument.wordprocessingml.document");values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/PaperFlow-QA");Uri uri=c.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);media.add(uri);try(InputStream in=new FileInputStream(document);OutputStream out=c.getContentResolver().openOutputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}Activity main=launch(MainActivity.class,new Intent());Instrumentation.ActivityMonitor monitor=inst.addMonitor(ExtendedToolsActivity.class.getName(),null,false);call(main,"importDocument",new Class<?>[]{Uri.class},uri);Activity converter=inst.waitForMonitorWithTimeout(monitor,15000);inst.removeMonitor(monitor);assertNotNull(converter);activities.add(converter);assertEquals("Office to PDF",f.field(converter,"operation"));await(()->!(Boolean)f.field(converter,"busy")&&!((ArrayList<?>)f.field(converter,"sources")).isEmpty());f.run((ExtendedToolsActivity)converter);File result=(File)f.field(converter,"result");outputs.add(result);try(PDDocument doc=PDDocument.load(result)){assertTrue(new PDFTextStripper().getText(doc).contains("Invoice"));}
    }
    final RemainingFeaturesTest f=new RemainingFeaturesTest();Instrumentation inst;Context c;final ArrayList<Activity> activities=new ArrayList<>();final ArrayList<File> outputs=new ArrayList<>();final ArrayList<Uri> media=new ArrayList<>();
    @Before public void setup(){f.setup();inst=f.inst;c=f.c;}
    @After public void cleanup(){for(Activity a:activities)inst.runOnMainSync(a::finish);for(File file:outputs){try(DocumentStore store=new DocumentStore(c)){store.db().delete("docs","path=?",new String[]{file.getPath()});}file.delete();}for(Uri uri:media)c.getContentResolver().delete(uri,null,null);f.cleanup();}
    android.widget.ListView findList(View view){if(view instanceof android.widget.ListView)return (android.widget.ListView)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.widget.ListView found=findList(group.getChildAt(i));if(found!=null)return found;}}return null;}
    interface Check {boolean ready()throws Exception;}
    void await(Check check)throws Exception{long end=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<end){if(check.ready())return;Thread.sleep(50);}fail("Operation timed out");}
    Activity launch(Class<?> type,Intent intent){Activity a=inst.startActivitySync(intent.setClass(c,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));activities.add(a);return a;}
    void call(Object owner,String method,Class<?>[] types,Object...args){inst.runOnMainSync(()->{try{f.invoke(owner,method,types,args);}catch(Exception e){throw new RuntimeException(e);}});}
    File locked(String name)throws Exception{File plain=f.nativePdf(name+"-plain.pdf",2),out=new File(f.dir,name+".pdf");try(PDDocument doc=PDDocument.load(plain)){StandardProtectionPolicy policy=new StandardProtectionPolicy("qa-owner-secret","secret123",new AccessPermission());policy.setEncryptionKeyLength(128);policy.setPreferAES(true);doc.protect(policy);doc.save(out);}return out;}
    void protectedCopy(File file,int pages)throws Exception{try(PDDocument ignored=PDDocument.load(file)){fail("Copy opened without password");}catch(InvalidPasswordException expected){}try(PDDocument doc=PDDocument.load(file,"secret123")){assertTrue(doc.isEncrypted());assertEquals(pages,doc.getNumberOfPages());assertTrue(new PDFTextStripper().getText(doc).contains("Invoice"));}}
    @Test public void extractReorderAndExplicitPasswordRemoval()throws Exception{File source=locked("qa-copy-protection");byte[] before=f.bytes(source);for(String operation:new String[]{"Extract PDF Pages","Reorder Pages","Remove PDF password"}){Activity a=launch(ToolWorkflowActivity.class,new Intent().putExtra("operation",operation).putExtra("path",source.getPath()).putExtra("pdf_password","secret123"));await(()->"options".equals(f.field(a,"stage")));call(a,"process",new Class<?>[0]);await(()->"result".equals(f.field(a,"stage")));File result=(File)f.field(a,"resultFile");outputs.add(result);if(operation.equals("Remove PDF password"))try(PDDocument doc=PDDocument.load(result)){assertFalse(doc.isEncrypted());assertEquals(2,doc.getNumberOfPages());}else protectedCopy(result,2);}assertArrayEquals(before,f.bytes(source));}
    @Test public void addingImportedPdfRetainsPassword()throws Exception{File source=locked("qa-appending"),extra=f.nativePdf("qa-extra.pdf",1);byte[] before=f.bytes(source);Activity main=launch(MainActivity.class,new Intent());f.set(main,"pendingAppendPath",source.getPath());f.set(main,"pendingAppendName","QA appended");f.set(main,"pendingAppendPassword","secret123");Instrumentation.ActivityMonitor monitor=inst.addMonitor(PdfViewerActivity.class.getName(),null,false);call(main,"appendImportedPdf",new Class<?>[]{Uri.class},Uri.fromFile(extra));Activity viewer=inst.waitForMonitorWithTimeout(monitor,30000);inst.removeMonitor(monitor);assertNotNull(viewer);activities.add(viewer);File result=new File(viewer.getIntent().getStringExtra("path"));outputs.add(result);protectedCopy(result,3);assertArrayEquals(before,f.bytes(source));}
    @Test public void keywordSearchSupportsRotationWholeWordsGreekAndOcr()throws Exception{File source=f.nativePdf("qa-keywords.pdf",2);try(PDDocument doc=PDDocument.load(source)){doc.getPage(1).setRotation(90);assertEquals(2,PdfKeywordSearch.search(c,doc,"INVOICE",true,(a,b)->{}).hits.size());assertEquals(90,doc.getPage(1).getRotation());assertEquals(0,PdfKeywordSearch.search(c,doc,"voice",true,(a,b)->{}).hits.size());assertEquals(2,PdfKeywordSearch.search(c,doc,"voice",false,(a,b)->{}).hits.size());}f.installEnglish();File raster=f.rasterPdf("qa-keyword-scan.pdf","SECRET ALPHA");try(PDDocument doc=PDDocument.load(raster)){assertEquals("OCR whole-word match",1,PdfKeywordSearch.search(c,doc,"SECRET",true,(a,b)->{}).hits.size());}ArrayList<PdfKeywordSearch.Glyph> greek=new ArrayList<>();greek.add(new PdfKeywordSearch.Glyph("Καλημέρα",new RectF(.1f,.1f,.3f,.2f)));assertEquals(1,PdfKeywordSearch.find(0,greek,DocumentStore.normalize("ΚΑΛΗΜΕΡΑ"),true).size());}
    @SuppressWarnings("unchecked") @Test public void folderMoveRejectsCycleAndClearsIndex()throws Exception{long root=0,child=0,target=0;File file=f.nativePdf("qa-folder-move.pdf",1);try(DocumentStore store=new DocumentStore(c)){ContentValues v=new ContentValues();v.put("name","QA root "+System.nanoTime());root=store.db().insertOrThrow("folders",null,v);v.put("parent",root);v.put("name","QA child");child=store.db().insertOrThrow("folders",null,v);v.put("parent",0);v.put("name","QA target");target=store.db().insertOrThrow("folders",null,v);store.registerDocument(file.getPath(),"QA move",1);v.clear();v.put("folder_id",child);v.put("search_text","private");store.db().update("docs",v,"path=?",new String[]{file.getPath()});try{FolderMoves.move(c,store,root,child);fail("Cycle accepted");}catch(IllegalArgumentException expected){}c.getSharedPreferences("folder_locks",0).edit().putString("pin_"+target,"qa").commit();Field field=FolderLock.class.getDeclaredField("sessions");field.setAccessible(true);((Map<Long,Long>)field.get(null)).put(target,SystemClock.elapsedRealtime()+300000);FolderMoves.move(c,store,root,target);try(Cursor row=store.db().rawQuery("SELECT parent FROM folders WHERE id=?",new String[]{Long.toString(root)})){assertTrue(row.moveToFirst());assertEquals(target,row.getLong(0));}try(Cursor row=store.db().rawQuery("SELECT search_text FROM docs WHERE path=?",new String[]{file.getPath()})){assertTrue(row.moveToFirst());assertEquals("",row.getString(0));}}finally{try(DocumentStore store=new DocumentStore(c)){store.db().delete("docs","path=?",new String[]{file.getPath()});for(long id:new long[]{child,root,target})store.db().delete("folders","id=?",new String[]{Long.toString(id)});}c.getSharedPreferences("folder_locks",0).edit().remove("pin_"+target).commit();inst.runOnMainSync(FolderLock::lockAll);}}
    @SuppressWarnings("unchecked") @Test public void expiryHidesOpenPageAndClosesSelectionAndDialog()throws Exception{File source=f.nativePdf("qa-expiry.pdf",1);long id;try(DocumentStore store=new DocumentStore(c)){ContentValues v=new ContentValues();v.put("name","QA expiry "+System.nanoTime());id=store.db().insertOrThrow("folders",null,v);store.registerDocument(source.getPath(),"QA expiry",1);v.clear();v.put("folder_id",id);store.db().update("docs",v,"path=?",new String[]{source.getPath()});}Field field=FolderLock.class.getDeclaredField("sessions");field.setAccessible(true);Map<Long,Long> sessions=(Map<Long,Long>)field.get(null);c.getSharedPreferences("folder_locks",0).edit().putString("pin_"+id,"qa").commit();sessions.put(id,SystemClock.elapsedRealtime()+300000);try{Activity a=launch(PdfViewerActivity.class,new Intent().putExtra("path",source.getPath()));await(()->!((ArrayList<?>)f.field(a,"slots")).isEmpty());call(a,"selectOnPage",new Class<?>[]{int.class,String.class},0,null);await(()->f.field(a,"selection")!=null);final Dialog[] dialog={null};inst.runOnMainSync(()->{try{dialog[0]=new android.app.AlertDialog.Builder(a).setTitle("QA private text").setMessage("private").create();for(Method m:FolderLock.class.getDeclaredMethods())if(m.getName().equals("trackDialog")){m.setAccessible(true);m.invoke(null,a,dialog[0]);}dialog[0].show();sessions.put(id,SystemClock.elapsedRealtime()+200);for(Method m:FolderLock.class.getDeclaredMethods())if(m.getName().equals("guard")){m.setAccessible(true);m.invoke(null,a,source.getPath());}}catch(Exception e){throw new RuntimeException(e);}});await(()->a.findViewById(android.R.id.content).findViewWithTag("folder-lock-shield")!=null);assertFalse(dialog[0].isShowing());assertNull(f.field(a,"selection"));assertFalse(a.isFinishing());}finally{c.getSharedPreferences("folder_locks",0).edit().remove("pin_"+id).commit();try(DocumentStore store=new DocumentStore(c)){store.db().delete("docs","path=?",new String[]{source.getPath()});store.db().delete("folders","id=?",new String[]{Long.toString(id)});}inst.runOnMainSync(FolderLock::lockAll);}}
    @SuppressWarnings("unchecked") @Test public void galleryPreservesOriginalAndRollsBackPendingCopies()throws Exception{Bitmap image=Bitmap.createBitmap(320,200,Bitmap.Config.ARGB_8888);image.eraseColor(Color.BLUE);File original=new File(f.dir,"qa-gallery.png");try(OutputStream out=new FileOutputStream(original)){image.compress(Bitmap.CompressFormat.PNG,100,out);}ArrayList<Uri> saved=new ArrayList<>();try(GalleryExport batch=new GalleryExport(c)){batch.original(Uri.fromFile(original).toString());batch.processed(image);saved.addAll((ArrayList<Uri>)f.field(batch,"pending"));assertEquals(2,saved.size());batch.commit();try(InputStream in=c.getContentResolver().openInputStream(saved.get(0));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);assertArrayEquals(f.bytes(original),out.toByteArray());}}finally{for(Uri uri:saved)c.getContentResolver().delete(uri,null,null);image.recycle();}Uri aborted;try(GalleryExport batch=new GalleryExport(c)){batch.original(Uri.fromFile(original).toString());aborted=((ArrayList<Uri>)f.field(batch,"pending")).get(0);}try(Cursor row=c.getContentResolver().query(aborted,null,null,null,null)){assertTrue(row==null||!row.moveToFirst());}}
    @SuppressWarnings("unchecked") @Test public void collageSupportsLandscapeSquareMultiplePagesAndZip()throws Exception{ExtendedToolsActivity a=(ExtendedToolsActivity)launch(ExtendedToolsActivity.class,new Intent().putExtra("operation","Collage"));ArrayList<ExtendedToolsActivity.Source> sources=(ArrayList<ExtendedToolsActivity.Source>)f.field(a,"sources");for(int i=0;i<3;i++){Bitmap image=Bitmap.createBitmap(200,300,Bitmap.Config.ARGB_8888);image.eraseColor(new int[]{Color.RED,Color.GREEN,Color.BLUE}[i]);File file=new File(f.dir,"qa-collage-"+i+".png");try(OutputStream out=new FileOutputStream(file)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();sources.add(new ExtendedToolsActivity.Source(file.getPath(),file.getName()));}f.set(a,"shape",1);f.set(a,"perPage",2);f.run(a);File result=(File)f.field(a,"result");outputs.add(result);try(PDDocument doc=PDDocument.load(result)){assertEquals(2,doc.getNumberOfPages());assertTrue(doc.getPage(0).getMediaBox().getWidth()>doc.getPage(0).getMediaBox().getHeight());}f.set(a,"result",null);f.set(a,"format",2);f.run(a);result=(File)f.field(a,"result");outputs.add(result);assertTrue(result.getName().endsWith(".zip"));try(ZipFile zip=new ZipFile(result)){assertEquals(2,zip.size());assertNotNull(zip.getEntry("page-001.png"));}f.set(a,"result",null);f.set(a,"format",0);f.set(a,"shape",2);f.set(a,"perPage",0);f.run(a);result=(File)f.field(a,"result");outputs.add(result);try(PDDocument doc=PDDocument.load(result)){assertEquals(1,doc.getNumberOfPages());assertEquals(doc.getPage(0).getMediaBox().getWidth(),doc.getPage(0).getMediaBox().getHeight(),.1f);}}
